var r=[{title:`Varifrån handledsbelastning kommer`,text:`Armhävningar och plankor på platta handflator böjer handleden långt bakåt. Hantel- och skivstångsövningar lägger till grepp och stabiliserande arbete. Obehag i handleden har många möjliga orsaker, och övningen ensam kan inte säga vilken det är.`},{title:`Ändra hur händerna möter golvet`,text:`Armhävningar med upphöjda händer lägger mindre av din vikt på armarna. Stabila handtag för armhävningar, eller hantlar som är säkrade så att de inte kan rulla, låter dig hålla handleden rakare. Underarmsplankor tar bort trycket från handflatorna helt. Vissa tycker också att en hantelpress med neutralt grepp är bekvämare än en press med rak stång.`},{title:`Håll ändringarna säkra`,text:`Använd aldrig hantlar som kan rulla som provisoriska handtag för armhävningar. Kontrollera att stöden är stabila och att underlaget inte kan glida. Tvinga inte en smärtsam handled in i en position bara för att en teknikanvisning kallar den ideal. Om en rörelse gör ont, avbryt och hitta ett bekvämt alternativ.`},{title:`Gå vidare långsamt`,text:`Bygg upp totalt antal repetitioner och kontroll innan du prövar svårare hävarm med kroppsvikt. Träffa en läkare vid ny smärta efter ett fall, kraftig svullnad, deformitet, stickningar eller förlorad styrka. Om obehaget i handleden fortsätter, låt en yrkesperson undersöka det, eftersom TrainUp inte kan diagnostisera det.`},{title:`Så använder du TrainUp`,text:`Lägg till dina handleder som en begränsning i Profil och ange din utrustning. Programmet väljer då övningar som passar, vilket kan inkludera bålträning på underarmarna. Efter ett pass kan du rapportera smärta med kroppsområde och övning, och använda anteckningarna för att följa hur dina handleder klarade det. TrainUp bygger inga rehabrutiner.`}];var e=[{label:`NHS: ledsmärta`,url:`https://www.nhs.uk/symptoms/joint-pain/`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:r,sources:e};export{t as default,r as sections,e as sources};